package com.aistock.market.refresh;
import com.aistock.common.BusinessException;import com.aistock.market.ingestion.CandidateRequestFilter;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Tag("mysql") class AdminRefreshContextMysqlTest {
 @Test void precheckReadsCurrentHeadWithoutMutatingAnyMarketRecords(){var f=new AdminRefreshFixture();String v=f.seed();var before=snapshot(f);var c=new AdminRefreshContextRepository(f.jdbc).find("SH600030",f.clock.instant());assertTrue(c.eligible());assertEquals(v,c.baseVersionId());assertEquals("1",c.headRevision());assertEquals(f.start,c.coverageStart());assertEquals(f.end,c.coverageEnd());assertEquals(before,snapshot(f));}
 @Test void noHeadAndUnavailableHeadAreNotEligible(){var f=new AdminRefreshFixture();f.jdbc.update("insert into instrument(instrument_id,ticker,display_name,demo_only)values('SH600030','SH600030','fixture',false)");var repo=new AdminRefreshContextRepository(f.jdbc);assertFalse(repo.find("SH600030",f.clock.instant()).eligible());String id=f.seed();f.jdbc.update("update market_data_version set status='UNAVAILABLE' where version_id=?",id);assertFalse(repo.find("SH600030",f.clock.instant()).eligible());assertThrows(BusinessException.class,()->repo.find("SH999999",f.clock.instant()));f.jdbc.update("update instrument set demo_only=true where instrument_id='SH600030'");try{assertThrows(BusinessException.class,()->repo.find("SH600030",f.clock.instant()));}finally{f.jdbc.update("update instrument set demo_only=false where instrument_id='SH600030'");}}
 @Test void wrongStockAndPriceBasisNeverLeakOtherVersionMetadata(){for(boolean wrongStock:new boolean[]{true,false}){var f=new AdminRefreshFixture();String id=f.seed();if(wrongStock){f.jdbc.update("insert into instrument(instrument_id,ticker,display_name,demo_only)values('SH600276','SH600276','other',false)");f.jdbc.update("update market_data_version set instrument_id='SH600276' where version_id=?",id);}else f.jdbc.update("update instrument_data_head set price_basis='OTHER' where version_id=?",id);var c=new AdminRefreshContextRepository(f.jdbc).find("SH600030",f.clock.instant());assertFalse(c.eligible());assertNull(c.baseVersionId());assertNull(c.coverageStart());}}
 @Test void unsupportedHistoricalCoverageIsNotEligible(){var f=new AdminRefreshFixture();String id=f.seed();f.jdbc.update("update market_data_version set coverage_start='1989-12-31' where version_id=?",id);assertFalse(new AdminRefreshContextRepository(f.jdbc).find("SH600030",f.clock.instant()).eligible());}
 @Test void internalControllerRequiresServiceCredentialAndHasNoPublicAlias()throws Exception{var f=new AdminRefreshFixture();f.seed();var mvc=MockMvcBuilders.standaloneSetup(new AdminRefreshContextController(new AdminRefreshContextRepository(f.jdbc),f.clock)).addFilters(new CandidateRequestFilter("fixture-service",4096)).build();String path="/internal/v1/market/admin-refresh-context/SH600030";mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header("X-Service-Token","fixture-service")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("data.instrumentId").value("SH600030")).andExpect(jsonPath("data.eligible").value(true));mvc.perform(get("/api/v1/admin-refresh-context/SH600030")).andExpect(status().isNotFound());}
 Map<String,List<Map<String,Object>>> snapshot(AdminRefreshFixture f){var map=new LinkedHashMap<String,List<Map<String,Object>>>();for(var table:List.of("instrument","instrument_data_head","market_data_version","market_daily_bar","market_calendar_day","market_refresh_receipt","market_ingestion_operation"))map.put(table,f.jdbc.queryForList("select * from "+table+" order by 1,2"));return map;}
}